//! Bake Blender .glb models into compiled-in vertex arrays.
//!
//! Unit and world models come from every part present (build/parts.rs): the platform's shared and
//! generic ones and each module's own, `<part>/assets/models/manifest.json` + the GLBs it names
//! (docs/models-ownership.md). The manifests are generated by `<part>/tools/blender/export_all.sh`
//! (platform/tools/blender/export_{units,world}.py), validated and merged by build/units.rs and
//! build/world.rs. Terrain props (sea stacks): the platform's "terrain" section +
//! platform/assets/models/terrain/*.glb (build/terrain.rs).
//! Static props (trees, rocks, coastal cliff, bridge): platform/tools/blender/*.py -> platform/assets/models/*.glb.
//! This script parses POSITION + COLOR_0 (rgb = albedo, a = team mask),
//! de-indexes, and computes flat face normals (low-poly look is guaranteed
//! here, not by Blender shading). Any violation fails the build loudly.
//! Runtime has no gltf dependency, no FS access, deterministic bytes.

use std::fmt::Write as _;
use std::path::PathBuf;

#[path = "build/glb.rs"]
mod glb;
#[path = "build/parts.rs"]
mod parts;
#[path = "build/units.rs"]
mod units;
#[path = "build/support.rs"]
mod support;
#[path = "build/world.rs"]
mod world;

#[path = "build/terrain.rs"]
mod terrain;

struct Spec {
    file: &'static str,
    symbol: &'static str,
    max_tris: usize,
    max_r: f32,
    max_y: f32,
}

const SPECS: &[Spec] = &[
    Spec {
        file: "visual-coastal-cliff.glb",
        symbol: "VISUAL_COASTAL_CLIFF",
        max_tris: 170,
        max_r: 0.6,
        max_y: 0.45,
    },
    Spec {
        file: "visual-rock-0.glb",
        symbol: "VISUAL_ROCK_0",
        max_tris: 250,
        max_r: 0.5,
        max_y: 0.8,
    },
    Spec {
        file: "visual-rock-1.glb",
        symbol: "VISUAL_ROCK_1",
        max_tris: 250,
        max_r: 0.5,
        max_y: 0.8,
    },
    Spec {
        file: "visual-rock-2.glb",
        symbol: "VISUAL_ROCK_2",
        max_tris: 250,
        max_r: 0.5,
        max_y: 0.8,
    },
    Spec {
        file: "visual-bridge.glb",
        symbol: "VISUAL_BRIDGE",
        max_tris: 1000,
        max_r: 0.5,
        max_y: 0.4,
    },
    Spec {
        file: "pine_0.glb",
        symbol: "PINE_0",
        max_tris: 300,
        max_r: 0.5,
        max_y: 1.5,
    },
    Spec {
        file: "pine_1.glb",
        symbol: "PINE_1",
        max_tris: 300,
        max_r: 0.5,
        max_y: 1.5,
    },
    Spec {
        file: "pine_2.glb",
        symbol: "PINE_2",
        max_tris: 300,
        max_r: 0.5,
        max_y: 1.5,
    },
];

fn sub(a: [f32; 3], b: [f32; 3]) -> [f32; 3] {
    [a[0] - b[0], a[1] - b[1], a[2] - b[2]]
}

fn cross(a: [f32; 3], b: [f32; 3]) -> [f32; 3] {
    [
        a[1] * b[2] - a[2] * b[1],
        a[2] * b[0] - a[0] * b[2],
        a[0] * b[1] - a[1] * b[0],
    ]
}

fn main() {
    let manifest = PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").unwrap());
    let models = manifest.join("../../assets/models");
    println!("cargo:rerun-if-changed=../../assets/models");
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed=build/units.rs");
    println!("cargo:rerun-if-changed=build/world.rs");
    println!("cargo:rerun-if-changed=build/parts.rs");
    println!("cargo:rerun-if-changed=build/support.rs");
    println!("cargo:rerun-if-changed=build/glb.rs");
    println!("cargo:rerun-if-changed=build/terrain.rs");
    let out = PathBuf::from(std::env::var("OUT_DIR").unwrap()).join("baked_models.rs");
    let mut code =
        String::from("// @generated by build.rs from assets/models/*.glb — do not edit.\n");

    for spec in SPECS {
        let path = models.join(spec.file);
        let (doc, buffers, _) = gltf::import(&path)
            .unwrap_or_else(|e| panic!("bake {}: import failed: {e}", spec.file));
        let mut pos: Vec<[f32; 3]> = Vec::new();
        let mut col: Vec<[f32; 4]> = Vec::new();
        for mesh in doc.meshes() {
            for prim in mesh.primitives() {
                assert_eq!(
                    prim.mode(),
                    gltf::mesh::Mode::Triangles,
                    "bake {}: non-triangle primitive (triangulate in Blender script)",
                    spec.file
                );
                let reader = prim.reader(|b| Some(&buffers[b.index()]));
                let p: Vec<[f32; 3]> = reader
                    .read_positions()
                    .unwrap_or_else(|| panic!("bake {}: POSITION missing", spec.file))
                    .collect();
                let c: Vec<[f32; 4]> = reader
                    .read_colors(0)
                    .unwrap_or_else(|| {
                        panic!("bake {}: COLOR_0 missing (paint in script)", spec.file)
                    })
                    .into_rgba_f32()
                    .collect();
                assert_eq!(
                    p.len(),
                    c.len(),
                    "bake {}: POSITION/COLOR_0 count mismatch",
                    spec.file
                );
                match reader.read_indices() {
                    Some(gltf::mesh::util::ReadIndices::U8(it)) => {
                        for i in it {
                            pos.push(p[i as usize]);
                            col.push(c[i as usize]);
                        }
                    }
                    Some(gltf::mesh::util::ReadIndices::U16(it)) => {
                        for i in it {
                            pos.push(p[i as usize]);
                            col.push(c[i as usize]);
                        }
                    }
                    Some(gltf::mesh::util::ReadIndices::U32(it)) => {
                        for i in it {
                            pos.push(p[i as usize]);
                            col.push(c[i as usize]);
                        }
                    }
                    None => {
                        pos.extend_from_slice(&p);
                        col.extend_from_slice(&c);
                    }
                }
            }
        }
        assert!(!pos.is_empty(), "bake {}: no vertices", spec.file);
        assert_eq!(
            pos.len() % 3,
            0,
            "bake {}: vertex count not a multiple of 3",
            spec.file
        );
        let tris = pos.len() / 3;
        assert!(
            tris <= spec.max_tris,
            "bake {}: {tris} tris exceed budget {}",
            spec.file,
            spec.max_tris
        );
        // Validate + emit flat normals.
        let mut verts = String::new();
        for t in 0..tris {
            let (a, b, c) = (pos[3 * t], pos[3 * t + 1], pos[3 * t + 2]);
            let mut n = cross(sub(b, a), sub(c, a));
            let len = (n[0] * n[0] + n[1] * n[1] + n[2] * n[2]).sqrt();
            assert!(len > 1e-9, "bake {}: degenerate triangle {t}", spec.file);
            n = [n[0] / len, n[1] / len, n[2] / len];
            for k in 0..3 {
                let (p, rgba) = (pos[3 * t + k], col[3 * t + k]);
                assert!(
                    p.iter().all(|v| v.is_finite()),
                    "bake {}: non-finite pos",
                    spec.file
                );
                assert!(p[1] >= -0.1, "bake {}: vertex below roots {p:?}", spec.file);
                assert!(
                    p[0].abs() <= spec.max_r && p[2].abs() <= spec.max_r,
                    "bake {}: footprint overflow {p:?}",
                    spec.file
                );
                assert!(p[1] <= spec.max_y, "bake {}: too tall {p:?}", spec.file);
                assert!(
                    rgba[0..3].iter().all(|v| (0.0..=1.0).contains(v)),
                    "bake {}: color out of gamut {rgba:?}",
                    spec.file
                );
                let team = rgba[3];
                assert!(
                    team == 0.0 || team == 1.0,
                    "bake {}: team mask must be 0/1, got {team}",
                    spec.file
                );
                let _ = write!(
                    verts,
                    "crate::gpu::buffers::UnitVertex {{ pos: [{:.5}, {:.5}, {:.5}], normal: [{:.5}, {:.5}, {:.5}], color: [{:.5}, {:.5}, {:.5}], team: {:.1} }},",
                    p[0], p[1], p[2], n[0], n[1], n[2],
                    rgba[0], rgba[1], rgba[2], team
                );
            }
        }
        let _ = write!(
            code,
            "pub const {}: &[crate::gpu::buffers::UnitVertex] = &[{}];\npub const {}_TRIS: usize = {};\n",
            spec.symbol, verts, spec.symbol, tris
        );
    }
    std::fs::write(out, code).unwrap();
    let out_dir = PathBuf::from(std::env::var("OUT_DIR").unwrap());
    // The models of every part present: the platform's shared and generic ones, then each
    // module's (build/parts.rs). The terrain props are the platform's alone.
    let platform = manifest.join("../..").canonicalize().unwrap();
    let parts = parts::discover(&platform);
    assert!(parts.first().is_some_and(parts::Part::is_platform), "the platform's assets/models/manifest.json is missing");
    // The animation classes of the models: the tables of the parts, platform first (gpu/world_anim.rs).
    let mut anim = String::new();
    for part in &parts {
        let table = part.models.join("world_anim.table");
        println!("cargo:rerun-if-changed={}", table.display());
        if let Ok(text) = std::fs::read_to_string(&table) {
            anim.push_str(&text);
            anim.push('\n');
        }
    }
    std::fs::write(out_dir.join("world_anim.table"), anim).unwrap();
    units::bake(&parts, &platform, &out_dir);
    world::bake(&parts, &platform, &out_dir);
    terrain::bake(&platform, &out_dir);
}
